      `https://api.elevenlabs.io/v1/convai/conversation/token?agent_id=${data.agentId}`,
      { headers: { "xi-api-key": process.env.ELEVENLABS_API_KEY! } },
    );
    const { token } = await r.json();
    return { token };
  });
```

